"use client"

import * as React from "react"
import { cn } from "cn"

import { Slider } from "@/components/ui/slider"
import { ColorSwatch } from "@/components/tecton/color-swatch"
import { Divider } from "@/components/tecton/divider"
import {
  SelectField,
  SelectFieldItem,
} from "@/components/tecton/select-field"
import { TextField } from "@/components/tecton/text-field"

import {
  getPair,
  getSurface,
  lineWidths,
  surfacePairs,
  volumes,
  type HorizonSettings,
} from "../data"

type HorizonFormProps = Omit<React.ComponentProps<"div">, "onChange"> & {
  value: HorizonSettings
  onChange: (next: HorizonSettings) => void
}

function HorizonForm({ className, value, onChange, ...props }: HorizonFormProps) {
  const pair = getPair(value.pairId)
  const top = getSurface(pair.top)
  const base = getSurface(pair.base)

  const set = <K extends keyof HorizonSettings>(key: K, next: HorizonSettings[K]) =>
    onChange({ ...value, [key]: next })

  return (
    <div
      data-slot="horizon-form"
      className={cn("flex flex-col gap-4", className)}
      {...props}
    >
      <SelectField
        label="Surface pair"
        variant="filled"
        selectedKey={value.pairId}
        onSelectionChange={(key) => {
          const next = getPair(String(key))
          onChange({
            ...value,
            pairId: next.id,
            topDepth: getSurface(next.top).depth,
            bottomDepth: getSurface(next.base).depth,
          })
        }}
      >
        {surfacePairs.map((item) => (
          <SelectFieldItem key={item.id} id={item.id} textValue={item.label}>
            {item.label}
          </SelectFieldItem>
        ))}
      </SelectField>

      <div className="grid grid-cols-2 gap-3">
        <SelectField
          label="Volume"
          variant="filled"
          selectedKey={value.volumeId}
          onSelectionChange={(key) => set("volumeId", String(key))}
        >
          {volumes.map((item) => (
            <SelectFieldItem key={item.id} id={item.id} textValue={item.label}>
              {item.label}
            </SelectFieldItem>
          ))}
        </SelectField>
        <SelectField
          label="Line"
          variant="filled"
          selectedKey={String(value.lineWidth)}
          onSelectionChange={(key) => set("lineWidth", Number(key))}
        >
          {lineWidths.map((width) => (
            <SelectFieldItem key={width} id={String(width)} textValue={`${width} px`}>
              <span className="font-mono tabular-nums">{width}</span>
              <span className="text-muted-foreground">px</span>
            </SelectFieldItem>
          ))}
        </SelectField>
      </div>

      <HorizonRow label="Horizon 1" surface={top} />
      <HorizonRow label="Horizon 2" surface={base} />

      <Divider emphasis="subtle" />

      <div className="grid grid-cols-2 gap-3">
        <TextField
          label="Top depth (TVDSS)"
          variant="filled"
          size="sm"
          type="number"
          value={String(value.topDepth)}
          onChange={(text) => set("topDepth", Number(text) || 0)}
          className="[&_input]:font-mono [&_input]:tabular-nums"
        />
        <TextField
          label="Bottom depth (TVDSS)"
          variant="filled"
          size="sm"
          type="number"
          value={String(value.bottomDepth)}
          onChange={(text) => set("bottomDepth", Number(text) || 0)}
          className="[&_input]:font-mono [&_input]:tabular-nums"
        />
      </div>

      <LabelledSlider
        label="Opacity"
        value={value.opacity}
        unit="%"
        minValue={0}
        maxValue={100}
        step={5}
        onChange={(next) => set("opacity", next)}
      />
      <LabelledSlider
        label="Smoothing"
        value={value.smoothing}
        unit="m"
        minValue={0}
        maxValue={100}
        step={5}
        onChange={(next) => set("smoothing", next)}
      />
    </div>
  )
}

function HorizonRow({
  label,
  surface,
}: {
  label: string
  surface: { code: string; name: string; color: string }
}) {
  return (
    <div data-slot="horizon-row" className="flex flex-col gap-1.5">
      <span className="text-xs text-muted-foreground">{label}</span>
      <div className="flex items-center gap-2 rounded-md bg-muted px-2.5 py-2 text-sm">
        <ColorSwatch
          color={surface.color}
          size="sm"
          shape="square"
          aria-label={`${surface.name} colour`}
        />
        <span className="font-mono text-xs text-muted-foreground">
          {surface.code}
        </span>
        <span className="min-w-0 flex-1 truncate">{surface.name}</span>
        <span className="font-mono text-xs text-muted-foreground uppercase">
          {surface.color.replace("#", "")}
        </span>
      </div>
    </div>
  )
}

function LabelledSlider({
  label,
  value,
  unit,
  minValue,
  maxValue,
  step,
  onChange,
}: {
  label: string
  value: number
  unit?: string
  minValue: number
  maxValue: number
  step?: number
  onChange: (value: number) => void
}) {
  return (
    <div data-slot="labelled-slider" className="flex flex-col gap-2">
      <div className="flex items-center justify-between text-xs">
        <span className="text-muted-foreground">{label}</span>
        <span className="font-mono tabular-nums">
          {value}
          {unit && <span className="text-muted-foreground">{unit}</span>}
        </span>
      </div>
      <Slider
        aria-label={label}
        value={value}
        minValue={minValue}
        maxValue={maxValue}
        step={step}
        onChange={(next) => onChange(Array.isArray(next) ? next[0] : next)}
      />
    </div>
  )
}

export { HorizonForm, HorizonRow, LabelledSlider }
export type { HorizonFormProps }

import * as React from "react"
import { cn } from "cn"

type ReadoutRow = {
  label: string
  value: React.ReactNode
  unit?: string
}

function HorizonReadout({
  className,
  rows,
  ...props
}: React.ComponentProps<"dl"> & { rows: ReadoutRow[] }) {
  return (
    <dl
      data-slot="horizon-readout"
      className={cn("flex flex-col gap-1.5 text-xs", className)}
      {...props}
    >
      {rows.map((row) => (
        <div key={row.label} className="flex items-baseline justify-between gap-3">
          <dt className="text-muted-foreground">{row.label}</dt>
          <dd className="font-mono tabular-nums">
            {row.value}
            {row.unit && <span className="text-muted-foreground">{row.unit}</span>}
          </dd>
        </div>
      ))}
    </dl>
  )
}

export { HorizonReadout }
export type { ReadoutRow }

"use client"

import * as React from "react"
import { cn } from "cn"
import { PanelRightIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Chip } from "@/components/tecton/chip"
import {
  Panel,
  PanelActions,
  PanelContent,
  PanelFooter,
  PanelHeader,
  PanelTitle,
} from "@/components/tecton/panel"

import { HorizonForm } from "./components/horizon-form"
import { HorizonReadout } from "./components/horizon-readout"
import {
  defaultHorizonSettings,
  getPair,
  volumes,
  type HorizonSettings,
} from "./data"

type HorizonsPanelProps = Omit<React.ComponentProps<typeof Panel>, "children"> & {
  initialSettings?: HorizonSettings
  onApply?: (value: HorizonSettings) => void
  onCollapse?: () => void
}

/**
 * "2 Horizons" tool panel — surface-pair picker, depth text fields,
 * opacity / smoothing sliders, colour tags and an Apply footer.
 */
function HorizonsPanel({
  className,
  initialSettings = defaultHorizonSettings,
  onApply,
  onCollapse,
  ...props
}: HorizonsPanelProps) {
  const [value, setValue] = React.useState<HorizonSettings>(initialSettings)
  const [applied, setApplied] = React.useState<HorizonSettings>(initialSettings)
  const dirty = JSON.stringify(value) !== JSON.stringify(applied)
  const pair = getPair(value.pairId)
  const volume = volumes.find((item) => item.id === value.volumeId)

  return (
    <Panel
      data-slot="horizons-panel"
      className={cn("h-full", className)}
      {...props}
    >
      <PanelHeader>
        <PanelTitle>2 Horizons</PanelTitle>
        <Chip size="xs" variant="outlined">
          {pair.label.split(" → ").length} surfaces
        </Chip>
        <PanelActions>
          <Button
            variant="ghost"
            size="icon-sm"
            aria-label="Collapse panel"
            onPress={onCollapse}
          >
            <PanelRightIcon />
          </Button>
        </PanelActions>
      </PanelHeader>
      <PanelContent className="flex flex-col gap-4">
        <HorizonForm value={value} onChange={setValue} />
        <HorizonReadout
          className="rounded-md bg-surface-alt/60 px-3 py-2"
          rows={[
            { label: "Volume", value: volume?.label ?? "—" },
            {
              label: "Top depth (TVDSS)",
              value: value.topDepth.toLocaleString(),
              unit: "m",
            },
            {
              label: "Bottom depth (TVDSS)",
              value: value.bottomDepth.toLocaleString(),
              unit: "m",
            },
            {
              label: "Thickness",
              value: Math.max(0, value.bottomDepth - value.topDepth).toLocaleString(),
              unit: "m",
            },
          ]}
        />
      </PanelContent>
      <PanelFooter className="justify-end">
        <Button
          variant="ghost"
          size="sm"
          isDisabled={!dirty}
          onPress={() => setValue(applied)}
        >
          Reset
        </Button>
        <Button
          size="sm"
          isDisabled={!dirty}
          onPress={() => {
            setApplied(value)
            onApply?.(value)
          }}
        >
          Apply
        </Button>
      </PanelFooter>
    </Panel>
  )
}

/** Route-ready page: the panel centred on the canvas. */
export default function HorizonsPanelPage() {
  return (
    <div
      data-slot="horizons-panel-page"
      className="flex min-h-svh w-full items-start justify-center bg-background px-4 py-8 text-foreground md:items-center"
    >
      <HorizonsPanel className="w-full max-w-sm" />
    </div>
  )
}

export { HorizonsPanel, HorizonForm, HorizonReadout }
export {
  surfaces,
  surfacePairs,
  volumes,
  defaultHorizonSettings,
} from "./data"
export type { HorizonsPanelProps }
export type { Surface, SurfacePair, HorizonSettings } from "./data"

export type Surface = {
  id: string
  /** Interpreter code, e.g. "K70". */
  code: string
  name: string
  /** Hex colour of the interpreted surface (from the project's colour table). */
  color: string
  /** Mean depth (TVDSS, metres). */
  depth: number
}

export type SurfacePair = {
  id: string
  label: string
  top: string
  base: string
}

export type HorizonSettings = {
  pairId: string
  volumeId: string
  topDepth: number
  bottomDepth: number
  lineWidth: number
  opacity: number
  smoothing: number
}

export const surfaces: Surface[] = [
  { id: "k70", code: "K70", name: "Spekk FM Top", color: "#218585", depth: 2525 },
  { id: "l70", code: "L70", name: "Are FM Top", color: "#2D7856", depth: 2639 },
  { id: "j80", code: "J80", name: "Melke FM Top", color: "#84A138", depth: 2481 },
  { id: "m10", code: "M10", name: "Garn FM Top", color: "#CB8553", depth: 2712 },
  { id: "m40", code: "M40", name: "Ile FM Top", color: "#8CA7DE", depth: 2790 },
  { id: "n20", code: "N20", name: "Tofte FM Top", color: "#C2867A", depth: 2874 },
]

export const surfacePairs: SurfacePair[] = [
  { id: "spekk-are", label: "Spekk FM Top → Are FM Top", top: "k70", base: "l70" },
  { id: "melke-spekk", label: "Melke FM Top → Spekk FM Top", top: "j80", base: "k70" },
  { id: "garn-ile", label: "Garn FM Top → Ile FM Top", top: "m10", base: "m40" },
  { id: "ile-tofte", label: "Ile FM Top → Tofte FM Top", top: "m40", base: "n20" },
]

export const volumes = [
  { id: "survey-2", label: "Survey 2" },
  { id: "survey-1", label: "Survey 1 (legacy)" },
  { id: "merged", label: "Merged PSDM" },
]

export const lineWidths = [1, 2, 3, 4, 6, 8]

export const defaultHorizonSettings: HorizonSettings = {
  pairId: "spekk-are",
  volumeId: "survey-2",
  topDepth: 2525,
  bottomDepth: 2639,
  lineWidth: 4,
  opacity: 85,
  smoothing: 20,
}

export function getSurface(id: string): Surface {
  return surfaces.find((surface) => surface.id === id) ?? surfaces[0]
}

export function getPair(id: string): SurfacePair {
  return surfacePairs.find((pair) => pair.id === id) ?? surfacePairs[0]
}
